class Store:
    def __init__(self):
        self.balance, self.last_token = 1000, 0

    def write(self, who, token, new, fencing):
        if fencing and token <= self.last_token:
            print(f"{who}: 토큰 {token} <= {self.last_token} → 거절")
            return
        self.balance, self.last_token = new, token
        print(f"{who}: 토큰 {token} 로 잔액 {new} 기록")

for fencing in (False, True):
    s = Store()
    a_seen = s.balance            # A: 락(토큰 1) 잡고 읽음 → GC 로 멈춤
    b_seen = s.balance            # 임대 만료, B: 락(토큰 2)
    s.write("B", 2, b_seen + 500, fencing)
    s.write("A", 1, a_seen - 300, fencing)
    print("최종 잔액", s.balance)
